    78→
    79→  /**
    80→   * Data columns sampled by the node as part of custody sampling
    81→   * https://github.com/ethereum/consensus-specs/blob/v1.6.0-alpha.4/specs/fulu/das-core.md#custody-sampling
    82→   *
    83→   * TODO: Consider race conditions if this updates during sync/backfill
    84→   */
    85→  sampledColumns: ColumnIndex[];
    86→
    87→  /**
    88→   * Subnets sampled by the node as part of custody sampling
    89→   */
    90→  sampledSubnets: number[];
    91→
    92→  private config: ChainForkConfig;
    93→  private nodeId: NodeId;
    94→
    95→  constructor(opts: CustodyConfigOpts) {
    96→    this.config = opts.config;
    97→    this.nodeId = opts.nodeId;
    98→    this.targetCustodyGroupCount = opts.initialCustodyGroupCount ?? this.config.CUSTODY_REQUIREMENT;
    99→    this.custodyColumns = getDataColumns(this.config, this.nodeId, this.targetCustodyGroupCount);
   100→    this.custodyColumnsIndex = this.getCustodyColumnsIndex(this.custodyColumns);
   101→    this.sampledGroupCount = Math.max(this.targetCustodyGroupCount, this.config.SAMPLES_PER_SLOT);
   102→    this.sampleGroups = getCustodyGroups(this.config, this.nodeId, this.sampledGroupCount);
   103→    this.sampledColumns = getDataColumns(this.config, this.nodeId, this.sampledGroupCount);
   104→    this.sampledSubnets = this.sampledColumns.map((columnIndex) =>
   105→      computeSubnetForDataColumn(this.config, columnIndex)
   106→    );
   107→  }
   108→
   109→  updateTargetCustodyGroupCount(targetCustodyGroupCount: number) {
   110→    this.targetCustodyGroupCount = targetCustodyGroupCount;
   111→    this.custodyColumns = getDataColumns(this.config, this.nodeId, this.targetCustodyGroupCount);
   112→    this.custodyColumnsIndex = this.getCustodyColumnsIndex(this.custodyColumns);
   113→    // TODO: Porting this over to match current behavior, but I think this incorrectly mixes units:
   114→    // SAMPLES_PER_SLOT is in columns, and CUSTODY_GROUP_COUNT is in groups
   115→    this.sampledGroupCount = Math.max(this.targetCustodyGroupCount, this.config.SAMPLES_PER_SLOT);
   116→    this.sampleGroups = getCustodyGroups(this.config, this.nodeId, this.sampledGroupCount);
   117→    this.sampledColumns = getDataColumns(this.config, this.nodeId, this.sampledGroupCount);
   118→    this.sampledSubnets = this.sampledColumns.map((columnIndex) =>
   119→      computeSubnetForDataColumn(this.config, columnIndex)
   120→    );
   121→  }
   122→
   123→  private getCustodyColumnsIndex(custodyColumns: ColumnIndex[]): Uint8Array {
   124→    // custody columns map which column maps to which index in the array of columns custodied
   125→    // with zero representing it is not custodied
   126→    const custodyColumnsIndex = new Uint8Array(NUMBER_OF_COLUMNS);
   127→    let custodyAtIndex = 1;
   128→    for (const columnIndex of custodyColumns) {
   129→      custodyColumnsIndex[columnIndex] = custodyAtIndex;
   130→      custodyAtIndex++;
   131→    }
   132→    return custodyColumnsIndex;
   133→  }
   134→}
   135→
   136→function computeSubnetForDataColumn(config: ChainForkConfig, columnIndex: ColumnIndex): number {
   137→  return columnIndex % config.DATA_COLUMN_SIDECAR_SUBNET_COUNT;
   138→}
   139→
   140→/**
   141→ * Calculate the number of custody groups the node should subscribe to based on the node's effective balance
   142→ *
   143→ * SPEC FUNCTION
   144→ * https://github.com/ethereum/consensus-specs/blob/v1.6.0-alpha.3/specs/fulu/validator.md#validator-custody
   145→ */
   146→export function getValidatorsCustodyRequirement(config: ChainForkConfig, effectiveBalances: number[]): number {
   147→  if (effectiveBalances.length === 0) {
   148→    return config.CUSTODY_REQUIREMENT;
   149→  }
   150→
   151→  const totalNodeEffectiveBalance = effectiveBalances.reduce((total, effectiveBalance) => {
   152→    return total + effectiveBalance;
   153→  }, 0);
   154→
   155→  // Must custody one group for every BALANCE_PER_ADDITIONAL_CUSTODY_GROUP of effective balance
   156→  let validatorsCustodyRequirement = Math.floor(
   157→    totalNodeEffectiveBalance / config.BALANCE_PER_ADDITIONAL_CUSTODY_GROUP
   158→  );
   159→
   160→  // Any node with at least 1 validator must custody at least VALIDATOR_CUSTODY_REQUIREMENT
   161→  validatorsCustodyRequirement = Math.max(validatorsCustodyRequirement, config.VALIDATOR_CUSTODY_REQUIREMENT);
   162→
   163→  // Cannot custody more than NUMBER_OF_CUSTODY_GROUPS
   164→  validatorsCustodyRequirement = Math.min(validatorsCustodyRequirement, config.NUMBER_OF_CUSTODY_GROUPS);
   165→
   166→  return validatorsCustodyRequirement;
   167→}
   168→
   169→/**
   170→ * Converts a custody group to an array of column indices.  Should be 1-1 as long there are 128
   171→ * columns and 128 custody groups.
   172→ *
   173→ * SPEC FUNCTION
   174→ * https://github.com/ethereum/consensus-specs/blob/v1.6.0-alpha.4/specs/fulu/das-core.md#compute_columns_for_custody_group
   175→ */
   176→export function computeColumnsForCustodyGroup(config: ChainForkConfig, custodyIndex: CustodyIndex): ColumnIndex[] {
   177→  if (custodyIndex >= config.NUMBER_OF_CUSTODY_GROUPS) {
   178→    throw Error(`Invalid custody index ${custodyIndex} >= ${config.NUMBER_OF_CUSTODY_GROUPS}`);
   179→  }
   180→  const columnsPerCustodyGroup = Number(NUMBER_OF_COLUMNS / config.NUMBER_OF_CUSTODY_GROUPS);
   181→  const columnIndexes = [];
   182→  for (let i = 0; i < columnsPerCustodyGroup; i++) {
   183→    columnIndexes.push(config.NUMBER_OF_CUSTODY_GROUPS * i + custodyIndex);
   184→  }
   185→  columnIndexes.sort((a, b) => a - b);
   186→  return columnIndexes;
   187→}
   188→
   189→/**
   190→ * Converts nodeId and a the number of custody groups to an array of custody indices. Indexes must be
   191→ * further converted to column indices
   192→ *
   193→ * SPEC FUNCTION
   194→ * https://github.com/ethereum/consensus-specs/blob/v1.6.0-alpha.4/specs/fulu/das-core.md#get_custody_groups
   195→ */
   196→export function getCustodyGroups(config: ChainForkConfig, nodeId: NodeId, custodyGroupCount: number): CustodyIndex[] {
   197→  if (custodyGroupCount > config.NUMBER_OF_CUSTODY_GROUPS) {
   198→    throw Error(`Invalid custody group count ${custodyGroupCount} > ${config.NUMBER_OF_CUSTODY_GROUPS}`);
   199→  }
   200→
   201→  // Skip computation if all groups are custodied
   202→  if (custodyGroupCount === config.NUMBER_OF_CUSTODY_GROUPS) {
   203→    return Array.from({length: config.NUMBER_OF_CUSTODY_GROUPS}, (_, i) => i);
   204→  }
   205→
   206→  const custodyGroups: CustodyIndex[] = [];
   207→  // nodeId is in bigendian and all computes are in little endian
   208→  let currentId = bytesToBigInt(nodeId, "be");
   209→  while (custodyGroups.length < custodyGroupCount) {
   210→    // could be optimized
   211→    const currentIdBytes = ssz.UintBn256.serialize(currentId);
   212→    const custodyGroup = Number(
   213→      ssz.UintBn64.deserialize(digest(currentIdBytes).slice(0, 8)) % BigInt(config.NUMBER_OF_CUSTODY_GROUPS)
   214→    );
   215→
   216→    if (!custodyGroups.includes(custodyGroup)) {
   217→      custodyGroups.push(custodyGroup);
   218→    }
   219→
   220→    const willOverflow = currentIdBytes.reduce((acc, elem) => acc && elem === 0xff, true);
   221→    if (willOverflow) {
   222→      currentId = BigInt(0);
   223→    } else {
   224→      currentId++;
   225→    }
   226→  }
   227→
   228→  custodyGroups.sort((a, b) => a - b);
   229→  return custodyGroups;
   230→}
   231→
   232→export function computePostFuluKzgCommitmentsInclusionProof(
   233→  fork: ForkName,
   234→  body: BeaconBlockBody
   235→): fulu.KzgCommitmentsInclusionProof {
   236→  const bodyView = (ssz[fork].BeaconBlockBody as SSZTypesFor<ForkAll, "BeaconBlockBody">).toView(body);
   237→  return new Tree(bodyView.node).getSingleProof(BigInt(KZG_COMMITMENTS_GINDEX));
   238→}
   239→
   240→export function getDataColumns(config: ChainForkConfig, nodeId: NodeId, custodyGroupCount: number): ColumnIndex[] {
   241→  return getCustodyGroups(config, nodeId, custodyGroupCount)
   242→    .flatMap((custodyIndex) => computeColumnsForCustodyGroup(config, custodyIndex))
   243→    .sort((a, b) => a - b);
   244→}
   245→
   246→/**
   247→ * Computes the cells for each blob and combines them with cell proofs.
   248→ * Similar to the computeMatrix function described below.
   249→ *
   250→ * SPEC FUNCTION (note: spec currently computes proofs, but we already have them)
   251→ * https://github.com/ethereum/consensus-specs/blob/v1.6.0-alpha.4/specs/fulu/das-core.md#compute_matrix
   252→ */
   253→export async function getCellsAndProofs(
   254→  blobBundles: fulu.BlobAndProofV2[]
   255→): Promise<{cells: Uint8Array[]; proofs: Uint8Array[]}[]> {
   256→  const blobsAndProofs: {cells: Uint8Array[]; proofs: Uint8Array[]}[] = [];
   257→  for (const {blob, proofs} of blobBundles) {
   258→    const cells = await kzg.asyncComputeCells(blob);
   259→    blobsAndProofs.push({cells, proofs});
   260→  }
   261→  return blobsAndProofs;
   262→}
   263→
   264→/**
   265→ * Given a signed block header and the commitments, inclusion proof, cells/proofs associated with
   266→ * each blob in the block, assemble the sidecars which can be distributed to peers.
   267→ *
   268→ * SPEC FUNCTION
   269→ * https://github.com/ethereum/consensus-specs/blob/v1.6.0-alpha.4/specs/fulu/validator.md#get_data_column_sidecars
   270→ */
   271→export function getDataColumnSidecars(
   272→  signedBlockHeader: SignedBeaconBlockHeader,
   273→  kzgCommitments: deneb.KZGCommitment[],
   274→  kzgCommitmentsInclusionProof: fulu.KzgCommitmentsInclusionProof,
   275→  cellsAndKzgProofs: {cells: Uint8Array[]; proofs: Uint8Array[]}[]
   276→): fulu.DataColumnSidecars {
   277→  if (cellsAndKzgProofs.length !== kzgCommitments.length) {
   278→    throw Error("Invalid cellsAndKzgProofs length for getDataColumnSidecars");
   279→  }
   280→
   281→  const sidecars: fulu.DataColumnSidecars = [];
   282→  for (let columnIndex = 0; columnIndex < NUMBER_OF_COLUMNS; columnIndex++) {
   283→    const columnCells = [];
   284→    const columnProofs = [];
   285→    for (const {cells, proofs} of cellsAndKzgProofs) {
   286→      columnCells.push(cells[columnIndex]);
   287→      columnProofs.push(proofs[columnIndex]);
   288→    }
   289→    sidecars.push({
   290→      index: columnIndex,
   291→      column: columnCells,
   292→      kzgCommitments,
   293→      kzgProofs: columnProofs,
   294→      signedBlockHeader,
   295→      kzgCommitmentsInclusionProof,
   296→    });
   297→  }
   298→  return sidecars;
   299→}
   300→
   301→/**
   302→ * Given a signed block and the cells/proofs associated with each blob in the
   303→ * block, assemble the sidecars which can be distributed to peers.
   304→ *
   305→ * SPEC FUNCTION
   306→ * https://github.com/ethereum/consensus-specs/blob/v1.6.0-alpha.4/specs/fulu/validator.md#get_data_column_sidecars_from_block
   307→ */
   308→export function getDataColumnSidecarsFromBlock(
   309→  config: ChainForkConfig,
   310→  signedBlock: SignedBeaconBlock<ForkPostFulu>,
   311→  cellsAndKzgProofs: {cells: Uint8Array[]; proofs: Uint8Array[]}[]
   312→): fulu.DataColumnSidecars {
   313→  // TODO GLOAS: Need to get blobKzgCommitments from somewhere else
   314→  const blobKzgCommitments = (signedBlock.message.body as BeaconBlockBody<ForkPostFulu & ForkPreGloas>)
   315→    .blobKzgCommitments;
   316→
   317→  // No need to create data column sidecars if there are no blobs
   318→  if (blobKzgCommitments.length === 0) {
   319→    return [];
   320→  }
   321→
   322→  const fork = config.getForkName(signedBlock.message.slot);
   323→  const signedBlockHeader = signedBlockToSignedHeader(config, signedBlock);
   324→
   325→  const kzgCommitmentsInclusionProof = computePostFuluKzgCommitmentsInclusionProof(fork, signedBlock.message.body);
   326→
   327→  return getDataColumnSidecars(signedBlockHeader, blobKzgCommitments, kzgCommitmentsInclusionProof, cellsAndKzgProofs);
   328→}
   329→
   330→/**
   331→ * Given a DataColumnSidecar and the cells/proofs associated with each blob corresponding
   332→ * to the commitments it contains, assemble all sidecars for distribution to peers.
   333→ *
   334→ * SPEC FUNCTION
   335→ * https://github.com/ethereum/consensus-specs/blob/v1.6.0-alpha.4/specs/fulu/validator.md#get_data_column_sidecars_from_column_sidecar
   336→ */
   337→export function getDataColumnSidecarsFromColumnSidecar(
   338→  sidecar: fulu.DataColumnSidecar,
   339→  cellsAndKzgProofs: {cells: Uint8Array[]; proofs: Uint8Array[]}[]
   340→): fulu.DataColumnSidecars {
   341→  return getDataColumnSidecars(
   342→    sidecar.signedBlockHeader,
   343→    sidecar.kzgCommitments,
   344→    sidecar.kzgCommitmentsInclusionProof,
   345→    cellsAndKzgProofs
   346→  );
   347→}
   348→
   349→/**
   350→ * If we receive more than half of NUMBER_OF_COLUMNS (64) we should recover all remaining columns
   351→ */
   352→export async function recoverDataColumnSidecars(
   353→  blockInput: BlockInputColumns,
   354→  emitter: ChainEventEmitter,
   355→  metrics: Metrics | null
   356→): Promise<DataColumnReconstructionCode> {
   357→  const existingColumns = blockInput.getAllColumns();
   358→  const columnCount = existingColumns.length;
   359→  if (columnCount >= NUMBER_OF_COLUMNS) {
   360→    // We have all columns
   361→    return DataColumnReconstructionCode.NotAttemptedAlreadyFull;
   362→  }
   363→
   364→  if (columnCount < NUMBER_OF_COLUMNS / 2) {
   365→    // We don't have enough columns to recover
   366→    return DataColumnReconstructionCode.NotAttemptedHaveLessThanHalf;
   367→  }
   368→
   369→  metrics?.recoverDataColumnSidecars.custodyBeforeReconstruction.set(columnCount);
   370→  const partialSidecars = new Map<number, fulu.DataColumnSidecar>();
   371→  for (const columnSidecar of existingColumns) {
   372→    // the more columns we put, the slower the recover
   373→    if (partialSidecars.size >= NUMBER_OF_COLUMNS / 2) {
   374→      break;
   375→    }
   376→    partialSidecars.set(columnSidecar.index, columnSidecar);
   377→  }
   378→
   379→  const timer = metrics?.recoverDataColumnSidecars.recoverTime.startTimer();
   380→  // if this function throws, we catch at the consumer side
   381→  const fullSidecars = await dataColumnMatrixRecovery(partialSidecars).catch(() => null);
   382→  timer?.();
   383→  if (fullSidecars == null) {
   384→    return DataColumnReconstructionCode.NullReturned;
   385→  }
   386→
   387→  if (blockInput.getAllColumns().length === NUMBER_OF_COLUMNS) {
   388→    // either gossip or getBlobsV2 resolved availability while we were recovering
   389→    return DataColumnReconstructionCode.SuccessLate;
   390→  }
   391→
   392→  // Once the node obtains a column through reconstruction,
   393→  // the node MUST expose the new column as if it had received it over the network.
   394→  // If the node is subscribed to the subnet corresponding to the column,
   395→  // it MUST send the reconstructed DataColumnSidecar to its topic mesh neighbors.
   396→  // If instead the node is not subscribed to the corresponding subnet,
   397→  // it SHOULD still expose the availability of the DataColumnSidecar as part of the gossip emission process.
   398→  // After exposing the reconstructed DataColumnSidecar to the network,
   399→  // the node MAY delete the DataColumnSidecar if it is not part of the node's custody requirement.
   400→  const sidecarsToPublish = [];
   401→  for (const columnSidecar of fullSidecars) {
   402→    if (!blockInput.hasColumn(columnSidecar.index)) {
   403→      blockInput.addColumn({
   404→        blockRootHex: blockInput.blockRootHex,
   405→        columnSidecar,
   406→        seenTimestampSec: Date.now() / 1000,
   407→        source: BlockInputSource.recovery,
   408→      });
   409→      sidecarsToPublish.push(columnSidecar);
   410→    }
   411→  }
   412→  emitter.emit(ChainEvent.publishDataColumns, sidecarsToPublish);
   413→
   414→  return DataColumnReconstructionCode.SuccessResolved;
   415→}
   416→
   417→export enum DataColumnReconstructionCode {
   418→  NotAttemptedAlreadyFull = "not_attempted_full",
   419→  NotAttemptedHaveLessThanHalf = "not_attempted_less_than_half",
   420→  NullReturned = "null_returned",
   421→  SuccessLate = "success_late",
   422→  SuccessResolved = "success_resolved",
   423→  Failed = "failed",
   424→}
   425→

